public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    int numVertices = target.getNumVertices();
    int numEdges = target.getNumEdges();
    List<GraphEdge> edges = target.getEdges();
    HashMap<Integer, GraphNode> nodeMap = target.getNodeMap();

    // Create two sets of vertices
    Set<Integer> set1 = new HashSet<>();
    Set<Integer> set2 = new HashSet<>();

    // Add vertices to sets based on their labels
    for (GraphEdge edge : edges) {
        if (edge.getSource().getLabel().equals("A")) {
            set1.add(edge.getSource().getId());
        } else {
            set2.add(edge.getSource().getId());
        }
    }

    // Create nodes for each set
    for (int vertex : set1) {
        GraphNode node1 = new GraphNode(vertex);
        nodeMap.put(vertex, node1);
        target.addNode(node1);
    }
    for (int vertex : set2) {
        GraphNode node2 = new GraphNode(vertex);
        nodeMap.put(vertex, node2);
        target.addNode(node2);
    }

    // Add edges between nodes from different sets
    for (GraphEdge edge : edges) {
        if (edge.getSource().getLabel().equals("A")) {
            target.addEdge(nodeMap.get(edge.getSource().getId()), nodeMap.get(edge.getTarget().getId()));
        } else {
            target.addEdge(nodeMap.get(edge.getSource().getId()), nodeMap.get(edge.getTarget().getId()));
        }
    }
}

